{
  "vulnerable_symbols": [
    "axios.defaults.xsrfCookieName",
    "axios.create",
    "axios.request",
    "axios/unsafe/helpers/cookies.js read"
  ],
  "trigger": "在浏览器中发起 axios 请求，且将攻击者可控的 xsrfCookieName（或 unsafe cookie helper name）配置为含正则元字符的字符串，使 axios 读取 document.cookie 时构造恶意正则。",
  "preconditions": [
    "运行在标准浏览器环境（存在 document.cookie，非 Node HTTP adapter、React Native 或 web worker）",
    "axios 版本为受影响版本（1.x <1.16.0 或 0.x <0.32.0）",
    "xsrfCookieName 非 null 且由攻击者可控输入设置，或 unsafe cookie helper 的 name 参数被攻击者控制",
    "请求路径会触发 XSRF cookie 读取（浏览器 XHR/fetch adapter）"
  ],
  "exploit_evidence": [
    {
      "src": 3,
      "kind": "poc",
      "quote": "Exploitation Public or AI PoC available; prioritize validation"
    },
    {
      "src": 2,
      "kind": "poc",
      "quote": "Snyk has a proof-of-concept or detailed explanation of how to exploit this vulnerability."
    }
  ],
  "fixed_version": "1.16.0",
  "summary_zh": "axios 浏览器端用未转义 XSRF cookie 名构造正则，外部可控名称可致 ReDoS；升级 1.16.0。"
}
